mapper.select:
SELECT sc.*, a.title as activity_title, vu.real_name as user_name FROM service_case sc LEFT JOIN activity a ON sc.activity_id = a.id LEFT JOIN volunteer_user vu ON sc.user_id = vu.id WHERE sc.user_id = #{userId} AND sc.deleted = 0
AND sc.case_type = #{caseType}
ORDER BY sc.created_time DESC

SELECT sc.*, a.title as activity_title, vu.real_name as user_name FROM service_case sc LEFT JOIN activity a ON sc.activity_id = a.id LEFT JOIN volunteer_user vu ON sc.user_id = vu.id WHERE sc.is_featured = 1 AND sc.status = 1 AND sc.deleted = 0
AND sc.case_type = #{caseType}
ORDER BY sc.created_time DESC

SELECT sc.*, a.title as activity_title, vu.real_name as user_name FROM service_case sc LEFT JOIN activity a ON sc.activity_id = a.id LEFT JOIN volunteer_user vu ON sc.user_id = vu.id WHERE sc.deleted = 0
AND (sc.title LIKE CONCAT('%', #{keyword}, '%') OR sc.content LIKE CONCAT('%', #{keyword}, '%') OR vu.real_name LIKE CONCAT('%', #{keyword}, '%'))
AND sc.case_type = #{caseType}
AND sc.status = #{status}
ORDER BY sc.created_time DESC
